#!/usr/bin/env node
/**
 * 前端 ↔ 后端命令一致性守护（M1-S4 spec §7 / §8.2）。
 *
 * 三件事：
 * 1. `src-tauri/src/commands_list.rs` 的 `COMMANDS` 与 `src/lib/api.ts` 的
 *    `INVOKED_COMMANDS` 必须是**同一个集合**（少一个 = 有命令没人调，多一个 = 调了不存在的命令）；
 * 2. `src-tauri/capabilities/default.json` 必须为每条命令声明 `allow-<kebab-case>`；
 * 3. **只有** `src/lib/api.ts` 允许 `import("@tauri-apps/api")`，页面组件必须走 api 层。
 * 4. `src-tauri/permissions/autogenerated/` 的文件集合必须与 `COMMANDS` 相同（B-25：
 *    命令改名/删除后旧文件不会被 `tauri-build` 清理，幽灵文件会让 `git status` 变脏）。
 *
 * 退出码非 0 即失败，供 `pnpm test` 使用。
 */

import { readFileSync, readdirSync, statSync } from "node:fs";
import { join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));

function fail(message) {
  console.error(`✗ ${message}`);
  process.exitCode = 1;
}

function ok(message) {
  console.log(`✓ ${message}`);
}

/** 去掉行注释，避免把被注释掉的命令也算进来（否则「删一条命令」抓不到） */
function stripLineComments(text) {
  return text.replace(/\/\/[^\n]*/g, "");
}

/** 从 `pub const COMMANDS: &[&str] = &[ "a", "b" ];` 里取出字符串字面量 */
function parseRustCommands() {
  const source = readFileSync(
    join(root, "src-tauri/src/commands_list.rs"),
    "utf8",
  );
  const block = source.match(/pub const COMMANDS[^=]*=\s*&\[([\s\S]*?)\];/);
  if (!block) throw new Error("在 commands_list.rs 里找不到 COMMANDS 数组");
  return [...stripLineComments(block[1]).matchAll(/"([^"]+)"/g)].map(
    (m) => m[1],
  );
}

/**
 * 从 `src/lib/api.ts` 里取出**真实被调用的**命令名。
 *
 * 解析的是 `invokeCommand<...>("cmd"` 这个调用点，而**不是**某个手工维护的镜像数组——
 * 镜像数组是假守护：把真实调用注释掉、数组不动，检查依然全绿
 * （M1-S3/S4 复审 P1 实测）。
 */
function parseTsCommands() {
  const source = stripLineComments(
    readFileSync(join(root, "src/lib/api.ts"), "utf8"),
  );
  const calls = [
    ...source.matchAll(/invokeCommand(?:<[^>]*>)?\(\s*"([a-z_]+)"/g),
  ].map((m) => m[1]);
  if (calls.length === 0) {
    throw new Error(
      "在 api.ts 里没解析到任何 invokeCommand(\"…\") 调用——解析器坏了，不能当成通过",
    );
  }
  return [...new Set(calls)];
}

function parseCapabilities() {
  const raw = readFileSync(
    join(root, "src-tauri/capabilities/default.json"),
    "utf8",
  );
  return JSON.parse(raw).permissions ?? [];
}

/** `list_sites` → `allow-list-sites`（Tauri 的权限名映射规则） */
function permissionFor(command) {
  return `allow-${command.replace(/_/g, "-")}`;
}

function walk(dir, out = []) {
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) walk(full, out);
    else if (/\.(ts|tsx)$/.test(entry)) out.push(full);
  }
  return out;
}

// ---------------------------------------------------------------- 1. 集合一致性

const rust = parseRustCommands();
const ts = parseTsCommands();

const onlyRust = rust.filter((c) => !ts.includes(c));
const onlyTs = ts.filter((c) => !rust.includes(c));

if (onlyRust.length) {
  fail(`后端有、前端未覆盖的命令：${onlyRust.join(", ")}`);
} else if (onlyTs.length) {
  fail(`前端调用了不存在的命令：${onlyTs.join(", ")}`);
} else {
  ok(`命令集合一致（${rust.length} 条）`);
}

// ---------------------------------------------------------------- 2. capabilities

const permissions = parseCapabilities();
const missing = rust
  .map(permissionFor)
  .filter((p) => !permissions.includes(p));

if (missing.length) {
  fail(`capabilities 缺少权限声明：${missing.join(", ")}`);
} else {
  ok(`capabilities 覆盖全部 ${rust.length} 条命令`);
}

// ---------------------------------------------------------------- 3. 唯一入口

const srcFiles = walk(join(root, "src"));
const offenders = srcFiles
  .filter((file) => relative(root, file) !== "src/lib/api.ts")
  .filter((file) => readFileSync(file, "utf8").includes("@tauri-apps/api"));

if (offenders.length) {
  fail(
    `只有 src/lib/api.ts 可以直接引用 @tauri-apps/api，违规文件：\n  ${offenders
      .map((f) => relative(root, f))
      .join("\n  ")}`,
  );
} else {
  ok("只有 src/lib/api.ts 直接引用 @tauri-apps/api");
}

// ------------------------------------------------- 4. 权限生成物 == 命令集合（B-25）

/**
 * `tauri-build` 按 `COMMANDS` 生成 `src-tauri/permissions/autogenerated/<command>.toml`。
 * 命令改名 / 删除后旧文件**不会被清理**（M1-S1 的 `zz_ghost_probe.toml` 就是这么留下的，
 * 源码恢复后它还在，`git status` 因此变脏），而「没跑过构建」又会表现为缺文件。
 * 所以两个方向都要红，并且报错必须直接指出**哪个文件 / 哪条命令**。
 */
const AUTOGENERATED_DIR = join(root, "src-tauri/permissions/autogenerated");

function listAutogeneratedFiles() {
  let entries;
  try {
    entries = readdirSync(AUTOGENERATED_DIR, { withFileTypes: true });
  } catch (error) {
    throw new Error(
      `读不到 ${relative(root, AUTOGENERATED_DIR)}/（${error.code}）。` +
        "该目录的生成物是**入库**的（B-25），缺失说明它被删了或被 .gitignore 掉了",
    );
  }
  return (
    entries
      .filter((entry) => entry.isFile())
      // macOS 的 Finder 会往目录里塞 .DS_Store；它不是权限生成物，不算幽灵
      .filter((entry) => !entry.name.startsWith("."))
      .map((entry) => entry.name)
      .sort()
  );
}

const expectedPermissionFiles = rust.map((command) => `${command}.toml`).sort();
const actualPermissionFiles = listAutogeneratedFiles();

const ghostFiles = actualPermissionFiles.filter(
  (file) => !expectedPermissionFiles.includes(file),
);
const missingFiles = expectedPermissionFiles.filter(
  (file) => !actualPermissionFiles.includes(file),
);

// 两个方向**分别**报，不写成 if/else（M5-S6 复审 P2-1）：
// 幽灵与缺失同时存在时，只报前者会让「构建没跑过 / 生成物被删」这条线索完全消失。
if (ghostFiles.length) {
  fail(
    `权限目录里有**幽灵文件**（COMMANDS 里没有对应的命令，tauri-build 不会清理）：\n  ${ghostFiles
      .map(
        (file) =>
          `${relative(root, join(AUTOGENERATED_DIR, file))}（COMMANDS 里没有「${file.replace(
            /\.toml$/,
            "",
          )}」）`,
      )
      .join("\n  ")}\n  处理：确认命令确实已改名 / 删除后，手动删掉这些文件（B-25）`,
  );
}
if (missingFiles.length) {
  fail(
    `权限目录**缺少生成物**（命令在 COMMANDS 里，却没有对应的权限文件）：\n  ${missingFiles
      .map(
        (file) =>
          `${relative(root, join(AUTOGENERATED_DIR, file))}（在 src-tauri/ 跑一次构建会生成它）`,
      )
      .join("\n  ")}`,
  );
}
if (!ghostFiles.length && !missingFiles.length) {
  ok(
    `权限生成物与命令集合一致（${actualPermissionFiles.length} 个文件 == ${rust.length} 条命令）`,
  );
}

if (process.exitCode) {
  console.error("\n命令一致性检查未通过。");
} else {
  console.log("\n命令一致性检查通过。");
}
